/**
 * The inline R helper definitions the exporter can emit, keyed by the name a
 * mark requests one by. A script carries only the helpers it references, so a
 * reader gets plain rtracklayer and ggplot2 they can edit in place.
 */
export const HELPERS: Record<string, string> = {
  bind_groups: "# rbind the frames a split produced, or a frame with 'columns' and no rows where\n# it produced none: do.call(rbind, list()) is NULL, and a NULL frame fails every\n# step and layer after it, where an empty window is a state the browser draws\n# as an empty panel.\nbind_groups <- function(parts, columns) {\n  out <- do.call(rbind, parts)\n  if (is.null(out)) {\n    out <- data.frame(setNames(rep(list(logical(0)), length(columns)), columns),\n                      check.names = FALSE)\n  }\n  out\n}",
  read_bigwig: "# Read a BigWig region into a data.frame(seqnames, start, end, score). start is\n# 0-based half-open (BED-style), like every other reader here - rtracklayer hands\n# back 1-based inclusive GRanges coordinates, so the start is shifted back by one.\n# That conversion is what makes adjacent bins ABUT: a bigwig's bins tile the\n# genome, and left as 1-based each bar was drawn one bp right of its true span\n# with a 1bp hole against its neighbour. Sub-pixel at any normal zoom, but the\n# device antialiases each rect separately, so the holes beat against the pixel\n# grid and surfaced as scattered full-height white seams through a solid xyplot.\nread_bigwig <- function(uri, chrom, start, end) {\n  df <- as.data.frame(rtracklayer::import(uri, which = GRanges(chrom, IRanges(start + 1, end))))\n  df$start <- df$start - 1L\n  df\n}",
  read_gff: "# Read the GFF3 features in a region through the file's tabix index into a\n# data.frame(start, end, strand, type, source, score, phase, id, parent, name),\n# plus one column per name in 'attrs', the column-9 attributes the display\n# reads: matched without regard to case, as JBrowse matches them; numeric where\n# every value parses as a number, as a channel reads it; all NA where the file\n# lacks the attribute. start is 0-based half-open. A contig the index lacks\n# reads as no features, as the browser draws it.\nread_gff <- function(uri, chrom, start, end, attrs = character(0)) {\n  tf <- TabixFile(uri)\n  g <- if (!chrom %in% seqnamesTabix(tf)) GRanges() else withCallingHandlers(\n    import(tf, which = GRanges(chrom, IRanges(start + 1, end)), format = \"gff3\"),\n    # rtracklayer rewinds the connection it opened itself and warns about it\n    warning = function(w) if (grepl(\"rewinding\", conditionMessage(w))) invokeRestart(\"muffleWarning\"))\n  m <- mcols(g)\n  # A GFF attribute can hold a comma list, which rtracklayer surfaces as a\n  # CharacterList - and as.character() on one errors rather than flattening, so\n  # join it back to the spelling the file used.\n  col <- function(nm) {\n    hit <- match(tolower(nm), tolower(names(m)))\n    v <- if (is.na(hit)) NULL else m[[hit]]\n    if (is.null(v)) rep(NA_character_, length(g))\n    else if (methods::is(v, \"List\")) vapply(v, function(x)\n      if (length(x)) paste(as.character(x), collapse = \",\") else NA_character_,\n      character(1))\n    else as.character(v)\n  }\n  parent <- if (is.null(m$Parent)) rep(NA_character_, length(g)) else\n    vapply(m$Parent, function(v) if (length(v)) as.character(v[[1]]) else NA_character_, character(1))\n  df <- data.frame(start = start(g) - 1L, end = end(g), strand = as.character(strand(g)),\n             type = col(\"type\"), source = col(\"source\"),\n             score = suppressWarnings(as.numeric(col(\"score\"))),\n             phase = suppressWarnings(as.integer(col(\"phase\"))),\n             id = col(\"ID\"), parent = parent, name = col(\"Name\"),\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (a in attrs) df[[a]] <- utils::type.convert(col(a), as.is = TRUE)\n  df\n}",
  read_regions: "# Read one data.frame per region with reader(chrom, start, end), shift the\n# columns 'coords' names onto the cumulative-bp axis region_layout() defines and\n# rbind the frames into one, with a '.region' column, so a single ggplot panel\n# spans several discontiguous regions on one x-axis. 'reader' answers a\n# genomic-coordinate data.frame, with no rows for a region holding nothing.\n# A feature is clipped to its region only where there is more than one: the\n# browser runs its transforms over the unclipped feature and clips the drawing,\n# which coord_cartesian() does for a lone region, while on a shared axis a\n# feature past its region's edge would draw over the gap into the next region.\nread_regions <- function(reader, regions, coords, clip = nrow(regions) > 1) {\n  parts <- lapply(seq_len(nrow(regions)), function(i) {\n    df <- reader(regions$chrom[i], regions$start[i], regions$end[i])\n    shift <- regions$offset[i] - regions$start[i]\n    for (col in coords) {\n      v <- df[[col]]\n      if (clip) v <- pmin(pmax(v, regions$start[i]), regions$end[i])\n      df[[col]] <- v + shift\n    }\n    df$.region <- rep(i, nrow(df))\n    df\n  })\n  do.call(rbind, parts)\n}",
  read_vcf: "# Read VCF records in a region via the tabix index (Rsamtools - no\n# VariantAnnotation needed) into data.frame(start, end, name, REF, ALT, QUAL,\n# FILTER, type), plus one INFO.<key> column per key in 'info', the INFO fields\n# the display reads - a flag key is TRUE where present and NA where not, and a\n# column every value of which parses as a number becomes numeric. SV span (END)\n# and SVTYPE come from INFO; sequence indels are classed by REF/ALT length.\n# start is 0-based half-open (BED-style). A contig the index lacks reads as no\n# records, as the browser draws it.\nread_vcf <- function(uri, chrom, start, end, info = character(0)) {\n  info_field <- function(inf, key) {\n    pat <- paste0(\"(?:^|;)\", key, \"(?:=([^;]*))?(?:;|$)\")\n    vapply(inf, function(x) {\n      m <- regmatches(x, regexec(pat, x, perl = TRUE))[[1]]\n      if (!length(m)) NA_character_ else if (nzchar(m[2])) m[2] else \"TRUE\"\n    }, character(1), USE.NAMES = FALSE)\n  }\n  tf <- TabixFile(uri)\n  lines <- if (!chrom %in% seqnamesTabix(tf)) character(0) else\n    unlist(scanTabix(tf, param = GRanges(chrom, IRanges(start + 1, end))))\n  cols <- if (length(lines)) do.call(rbind, strsplit(lines, \"\\t\", fixed = TRUE))\n          else matrix(character(), 0, 8)\n  pos <- as.integer(cols[, 2]); ref <- cols[, 4]\n  alt <- sub(\",.*\", \"\", cols[, 5]); inf <- cols[, 8]\n  symbolic <- grepl(\"^<\", alt)\n  end_info <- suppressWarnings(as.integer(info_field(inf, \"END\")))\n  svtype <- info_field(inf, \"SVTYPE\")\n  type <- ifelse(symbolic,\n      ifelse(!is.na(svtype), svtype, gsub(\"[<>]\", \"\", alt)),\n    ifelse(nchar(ref) == 1 & nchar(alt) == 1, \"SNV\",\n      ifelse(nchar(ref) < nchar(alt), \"INS\",\n        ifelse(nchar(ref) > nchar(alt), \"DEL\", \"MNV\"))))\n  df <- data.frame(start = pos - 1L,\n             end = ifelse(symbolic & !is.na(end_info), end_info, pos + nchar(ref) - 1L),\n             name = ifelse(cols[, 3] == \".\", NA_character_, cols[, 3]),\n             REF = ref, ALT = alt,\n             QUAL = suppressWarnings(as.numeric(cols[, 6])),\n             FILTER = cols[, 7], type = type,\n             stringsAsFactors = FALSE, check.names = FALSE)\n  for (k in info) df[[paste0(\"INFO.\", k)]] <-\n    utils::type.convert(info_field(inf, k), as.is = TRUE)\n  df\n}",
  region_layout: "# Lay a set of displayed regions out on one continuous \"cumulative bp\" x-axis,\n# the way JBrowse concatenates several regions in a single linear view: each\n# region occupies a span proportional to its bp width, with a small gap between\n# them. 'regions' is a data.frame(chrom, start, end) (0-based half-open); this\n# adds offset (the region's left edge on the cumulative axis), width, gap, and\n# cum_start/cum_end. The first region is anchored at its own genomic start, so a\n# lone region keeps native genomic coordinates (a single-region figure is\n# unchanged). cum_pos for a position p in region i is offset[i] + (p - start[i]).\nregion_layout <- function(regions, gap_frac = 0.012) {\n  w <- regions$end - regions$start\n  gap <- max(1, round(sum(w) * gap_frac))\n  regions$offset <- regions$start[1] + head(cumsum(c(0, w + gap)), length(w))\n  regions$width <- w; regions$gap <- gap\n  regions$cum_start <- regions$offset; regions$cum_end <- regions$offset + w\n  regions\n}",
}
